src/models/resource-models.ts.numbered_source:
1: import { z } from "zod";
2: 
3: // Resource schemas
4: export const ResourceSchema = z.object({
5:   uri: z.string(),
6:   name: z.string(),
7:   description: z.string(),
8: });
9: 
10: export const ListResourcesResponseSchema = z.object({
11:   resources: z.array(ResourceSchema),
12: });
13: 
14: export const ReadResourceResponseSchema = z.object({
15:   contents: z.array(
16:     z.object({
17:       uri: z.string(),
18:       mimeType: z.string(),
19:       text: z.string(),
20:     })
21:   ),
22: });
23: 
24: export type K8sResource = z.infer<typeof ResourceSchema>;
25: 
26: // Resource tracking interfaces
27: export interface ResourceTracker {
28:   kind: string;
29:   name: string;
30:   namespace: string;
31:   createdAt: Date;
32: }
33: 
34: export interface PortForwardTracker {
35:   id: string;
36:   server: { stop: () => Promise<void> };
37:   resourceType: string;
38:   name: string;
39:   namespace: string;
40:   ports: { local: number; remote: number }[];
41: }
42: 
43: export interface WatchTracker {
44:   id: string;
45:   abort: AbortController;
46:   resourceType: string;
47:   namespace: string;
48: }

